#!/usr/bin/env python3
"""CLI and partial-expectation runner. Inputs are parsed as data, never executed."""

from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path
import sys
from typing import Any

from reader import Parameters, Reader, compare_readers


def load_json(path: Path) -> Any:
    def object_pairs(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
        result = {}
        for key, value in pairs:
            if key in result:
                raise ValueError("duplicate JSON object member: " + key)
            result[key] = value
        return result

    def invalid_constant(value: str) -> None:
        raise ValueError("invalid JSON constant: " + value)

    return json.loads(path.read_text(encoding="utf-8"), object_pairs_hook=object_pairs, parse_constant=invalid_constant)


def compare_expected(actual: Any, expected: Any, path: str = "$", *, root: bool = True) -> list[str]:
    """All specified fields compare recursively; only top-level expected.note is prose.

    Objects are partial, arrays have exact length/order, scalar types must match.
    Unspecified actual object fields are permitted, never fabricated in expected.
    """
    differences = []
    if isinstance(expected, dict):
        if not isinstance(actual, dict):
            return [f"{path}: expected object, got {actual!r}"]
        for key, value in expected.items():
            if root and key == "note":
                if not isinstance(value, str):
                    differences.append(f"{path}.note: prose annotation must be a string")
                continue
            child = path + "." + str(key)
            if key not in actual:
                differences.append(f"{child}: missing specified field")
            else:
                differences.extend(compare_expected(actual[key], value, child, root=False))
    elif isinstance(expected, list):
        if not isinstance(actual, list):
            return [f"{path}: expected array, got {actual!r}"]
        if len(actual) != len(expected):
            differences.append(f"{path}: expected {len(expected)} items, got {len(actual)}")
        for i, (have, want) in enumerate(zip(actual, expected)):
            differences.extend(compare_expected(have, want, f"{path}[{i}]", root=False))
    elif type(actual) is not type(expected) or actual != expected:
        differences.append(f"{path}: expected {expected!r} ({type(expected).__name__}), got {actual!r} ({type(actual).__name__})")
    return differences


def machine_leaves(value: Any, *, root: bool = True) -> int:
    if isinstance(value, dict):
        return sum(machine_leaves(v, root=False) for k, v in value.items() if not (root and k == "note"))
    if isinstance(value, list):
        return sum(machine_leaves(v, root=False) for v in value)
    return 1


def run_vectors(document: Any, *, trusted_bootstrap: bool = False) -> dict[str, Any]:
    if not isinstance(document, dict) or document.get("evp_vectors") != "0.1-draft":
        raise ValueError("expected evp_vectors=0.1-draft")
    params = Parameters.from_dict(document.get("params"))
    vectors = document.get("vectors")
    if not isinstance(vectors, list) or not vectors:
        raise ValueError("vectors must be a nonempty array")
    results, names = [], set()
    for vector in vectors:
        if not isinstance(vector, dict) or not isinstance(vector.get("name"), str) or not vector["name"]:
            raise ValueError("each vector requires a nonempty name")
        name = vector["name"]
        if name in names:
            raise ValueError("duplicate vector name: " + name)
        names.add(name)
        if not isinstance(vector.get("expected"), dict):
            raise ValueError("each vector requires an expected object")
        if ("log" in vector) == ("readers" in vector):
            raise ValueError("each vector requires exactly one of log/readers")
        if "log" in vector:
            actual = Reader(params, trusted_bootstrap=trusted_bootstrap).run(vector["log"])
        else:
            logs = vector["readers"]
            if not isinstance(logs, dict) or set(logs) != {"A", "B"}:
                raise ValueError("comparison vector requires A and B")
            a = Reader(params, trusted_bootstrap=trusted_bootstrap)
            b = Reader(params, trusted_bootstrap=trusted_bootstrap)
            actual = {"A": a.run(logs["A"]), "B": b.run(logs["B"]), **compare_readers(a, b)}
        differences = compare_expected(actual, vector["expected"])
        results.append({"name": name, "passed": not differences, "specified_machine_leaves": machine_leaves(vector["expected"]), "differences": differences, "actual": actual})
    return {"passed": sum(r["passed"] for r in results), "total": len(results), "specified_machine_leaves": sum(r["specified_machine_leaves"] for r in results), "trusted_bootstrap_opt_in": trusted_bootstrap, "results": results}


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    sub = parser.add_subparsers(dest="command", required=True)
    vector_parser = sub.add_parser("vectors", help="compare every explicitly expected machine field")
    vector_parser.add_argument("paths", nargs="+", type=Path)
    vector_parser.add_argument("--trusted-bootstrap-fixtures", action="store_true", help="explicitly trust pinless genesis in supplied test data")
    log_parser = sub.add_parser("run", help="process JSON {params, log}; print state and all verdicts")
    log_parser.add_argument("path", type=Path)
    log_parser.add_argument("--trusted-bootstrap", action="store_true", help="DANGER: symbolic trusted test bootstrap only")
    args = parser.parse_args(argv)
    try:
        if args.command == "run":
            data = load_json(args.path)
            if not isinstance(data, dict) or set(data) != {"params", "log"}:
                raise ValueError("log document requires exactly params and log")
            output = Reader(Parameters.from_dict(data["params"]), trusted_bootstrap=args.trusted_bootstrap).run(data["log"])
            status = 0
        else:
            files = []
            for path in args.paths:
                result = run_vectors(load_json(path), trusted_bootstrap=args.trusted_bootstrap_fixtures)
                files.append({"input": str(path), "input_file_sha256": hashlib.sha256(path.read_bytes()).hexdigest(), **result})
            output = {"passed": sum(f["passed"] for f in files), "total": sum(f["total"] for f in files), "files": files}
            status = 0 if output["passed"] == output["total"] else 1
        print(json.dumps(output, indent=2, sort_keys=True))
        return status
    except (ValueError, OSError) as exc:
        print(json.dumps({"error": str(exc)}), file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
```

