"""Independent EVP v0.1-draft symbolic reader. No cryptography or network I/O."""

from __future__ import annotations

from copy import deepcopy
from dataclasses import dataclass, field
import re
from typing import Any


class Rejection(Exception):
    """An event refusal with a stable machine-readable reason."""


def require(condition: bool, reason: str) -> None:
    if not condition:
        raise Rejection(reason)


def integer(value: Any, minimum: int = 0) -> bool:
    return type(value) is int and value >= minimum


def symbol(value: Any) -> bool:
    # Exclude delimiters to make the *symbolic* pin notation unambiguous.
    return isinstance(value, str) and re.fullmatch(r"[A-Za-z0-9_.:-]{1,256}", value) is not None


@dataclass(frozen=True)
class Parameters:
    k: int = 3
    f: int = 1
    t: int = 2
    W: int = 10

    def __post_init__(self) -> None:
        if any(type(x) is not int for x in (self.k, self.f, self.t, self.W)):
            raise ValueError("malformed_parameters: exact integer values required")
        if (self.k, self.f, self.t, self.W) != (3, 1, 2, 10):
            raise ValueError("unsupported_parameters: only published k=3,f=1,t=2,W=10")

    @classmethod
    def from_dict(cls, data: Any) -> "Parameters":
        if not isinstance(data, dict) or set(data) != {"k", "f", "t", "W"}:
            raise ValueError("malformed_parameters: require exactly k,f,t,W")
        return cls(**data)


@dataclass
class Domain:
    initialized: bool = False
    key: str | None = None
    recovery: str | None = None
    witnesses: frozenset[str] = frozenset()
    genesis: dict[str, Any] | None = None
    bootstrap: bool = False
    epoch: int = 0
    frozen: dict[str, Any] | None = None
    equivocated_epochs: set[int] = field(default_factory=set)
    grants: dict[int, dict[str, Any]] = field(default_factory=dict)
    reserved_keys: set[str] = field(default_factory=set)
    heads: dict[tuple[int, int], list[tuple[str, int]]] = field(default_factory=dict)
    writes: list[dict[str, Any]] = field(default_factory=list)
    batch: dict[str, Any] | None = None


class Reader:
    """Transactional symbolic processor; rejected events affect audit metadata only.

    trusted_bootstrap=True is ONLY for explicitly trusted incomplete test genesis.
    It is never inferred from the input, vector name, or expected result.
    """

    def __init__(self, params: Parameters | None = None, *, trusted_bootstrap: bool = False):
        if params is not None and not isinstance(params, Parameters):
            raise ValueError("params must be Parameters")
        if type(trusted_bootstrap) is not bool:
            raise ValueError("trusted_bootstrap must be bool")
        self.params = params or Parameters()
        self.trusted_bootstrap = trusted_bootstrap
        self._domain = Domain()
        self._high_watermark = 0
        self._seen: set[int] = set()
        self.verdicts: dict[str, str] = {}
        self.event_results: list[dict[str, Any]] = []

    @staticmethod
    def _shape(e: dict[str, Any], required: set[str], optional: set[str] | None = None) -> None:
        required = required | {"seq", "op"}
        require(required <= set(e) <= required | (optional or set()), "malformed_event")

    @staticmethod
    def _signers(value: Any) -> set[str]:
        if isinstance(value, str):
            values = [value]
        else:
            require(isinstance(value, list), "malformed_signers")
            values = value
        require(bool(values) and all(symbol(x) for x in values), "malformed_signers")
        return set(values)

    def _threshold(self, d: Domain, signers: set[str]) -> bool:
        return len(d.witnesses & signers) >= self.params.t

    @staticmethod
    def _initialized(d: Domain) -> None:
        require(d.initialized, "no_genesis")

    @staticmethod
    def _active(d: Domain) -> None:
        require(d.frozen is None, "frozen")
        require(d.epoch not in d.equivocated_epochs, "equivocated")

    @staticmethod
    def _current_key(d: Domain, signers: set[str]) -> None:
        require(d.key in signers, "unknown_key")

    @staticmethod
    def _cancel_pending(d: Domain) -> None:
        for grant in d.grants.values():
            if grant["status"] == "pending":
                grant["status"] = "cancelled"

    @staticmethod
    def _no_pending(d: Domain) -> None:
        require(not any(g["status"] == "pending" for g in d.grants.values()), "pending_grant_exists")

    @staticmethod
    def _fresh(d: Domain, key: Any) -> None:
        require(symbol(key), "malformed_key")
        require(key not in d.reserved_keys and key != d.recovery and key not in d.witnesses, "key_not_fresh")

    @staticmethod
    def _anchor(e: dict[str, Any]) -> None:
        require(integer(e.get("anchor_seq"), 1), "malformed_anchor")
        # Backdating and future dating are outside this conservative local profile.
        require(e["anchor_seq"] == e["seq"], "anchor_mismatch")

    def apply(self, event: Any) -> str:
        """Consume one event; return a verdict, including for malformed/rejected input.

        A valid integer seq is consumed for ingestion ordering even if its event is
        rejected. No protocol state, accepted data, or authority changes on refusal.
        """
        seq = event.get("seq") if isinstance(event, dict) else None
        valid_seq = integer(seq, 1)
        try:
            require(isinstance(event, dict), "malformed_event")
            require(valid_seq, "malformed_seq")
            if seq in self._seen:
                raise Rejection("duplicate_seq")
            self._seen.add(seq)
            require(seq > self._high_watermark, "out_of_order_seq")
            self._high_watermark = seq
            require(isinstance(event.get("op"), str), "malformed_operation")
            # Only a completely accepted candidate replaces the accepted domain.
